# Test: each row's position determines expansion
# Row 0 → 2 copies, Row 1 → 1 copy, Row 2 → 2 copies

d1_in = [[6, 5, 5], [5, 1, 7], [4, 5, 2]]
d2_in = [[1, 3, 5], [1, 2, 8], [8, 3, 8]]

def transform_input_col(col):
    """Transform using row index to determine expansion"""
    output_col = []
    for i, v in enumerate(col):
        if i == 0 or i == 2:  # Row 0 and 2 → 2 copies
            output_col.extend([v, v])
        else:  # Row 1 → 1 copy
            output_col.append(v)
    return output_col

print("Testing hypothesis (row index determines expansion):")
for demo_name, (d_in, d_out, demo_num) in [("Demo 1", (d1_in, d1_out, 1)), ("Demo 2", (d2_in, None, 2))]:
    print(f"\n{demo_name}:")
    for c in range(3):
        input_col = [d_in[r][c] for r in range(3)]
        expanded = transform_input_col(input_col)
        print(f"  Input col {c} {input_col}")

        if demo_num == 1:
            # Demo 1: col 0 → output cols 0-1, col 1 → output col 2, col 2 → output cols 3-4
            if c == 0:
                actual = [d_out[r][0] for r in range(5)]
            elif c == 1:
                actual = [d_out[r][2] for r in range(5)]
            else:
                actual = [d_out[r][3] for r in range(5)]
        else:
            # Demo 2: same mapping should apply
            if c == 0:
                actual = [d_out[r][0] for r in range(5)] if d_out else "N/A"
            elif c == 1:
                actual = [d_out[r][2] for r in range(5)] if d_out else "N/A"
            else:
                actual = [d_out[r][3] for r in range(5)] if d_out else "N/A"

            print(f"    Expanded: {expanded}")
            print(f"    Actual: {actual if actual == 'N/A' else actual}")
            print(f"    Match: {expanded == actual if actual != 'N/A' else 'SKIP'}")

        if demo_num == 1:
            print(f"    Match: {expanded == actual}")
